use anyhow::Result;use clap::Parser;use destiny_protocol_analyzer::{open_database,ingest,CapturePacket};use tokio::{io::AsyncReadExt,net::TcpListener};use std::time::{SystemTime,UNIX_EPOCH};
#[derive(Parser)]struct A{#[arg(short,long,default_value="127.0.0.1:39000")]listen:String,#[arg(short,long,default_value="protocol.db")]database:String}
#[tokio::main]async fn main()->Result<()>{let a=A::parse();let db=open_database(&a.database)?;let listener=TcpListener::bind(&a.listen).await?;println!("destiny-rpcs3-harness listening on {}",listener.local_addr()?);loop{let(mut stream,peer)=listener.accept().await?;println!("connection observed from {peer}");let mut payload=Vec::new();stream.read_to_end(&mut payload).await?;let ts=SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_millis();ingest(&db,&CapturePacket{session_id:peer.to_string(),direction:"unknown".into(),timestamp_ms:ts,payload:payload.clone(),opcode:None,confidence:"unknown".into(),notes:"raw harness observation; handshake and opcode unmapped".into()})?;println!("captured {} raw bytes; handshake/opcodes remain unknown",payload.len());}}
